def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # If value is a datetime.time instance, use isoformat to serialize
    try:
        return value.isoformat()
    except AttributeError:
        # Fallback: try to format manually
        return str(value)

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    return {'x': value.x, 'y': value.y}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._record.keys())

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        handler = cls._protocol_handlers.get(protocol_version)
        if handler and getattr(handler, 'supported', True):
            return {protocol_version: handler}
        return {}
    return {v: h for v, h in cls._protocol_handlers.items() if getattr(h, 'supported', True)}

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying data structure.  Most record
    # implementations store their data in a dictionary called
    # `_data`.  If that attribute is missing we fall back to the
    # instance's own dictionary, ignoring private attributes.
    data = getattr(self, "_data", None)
    if data is None:
        data = {k: v for k, v in self.__dict__.items() if not k.startswith("_")}

    # If no keys are supplied, return all values.
    if not keys:
        return list(data.values())

    # Build a list of requested values.  Keys may be either a
    # string (dictionary key) or an integer (index into the
    # values list).  Mixed types are supported.
    values = list(data.values())
    result = []
    for key in keys:
        if isinstance(key, int):
            try:
                result.append(values[key])
            except IndexError:
                raise KeyError(f"Index {key} out of range")
        else:
            if key in data:
                result.append(data[key])
            else:
                raise KeyError(f"Key {key!r} not found")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys specified, return all items
    if not keys:
        return dict(zip(self._keys, self._data))
    result = {}
    for k in keys:
        if isinstance(k, int):
            # index access
            if k < 0 or k >= len(self._data):
                raise IndexError(f"Index {k} out of bounds")
            key = self._keys[k]
            result[key] = self._data[k]
        else:
            # key access
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._data[idx]
            else:
                result[k] = None
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Define the constructor for the new subclass
    def __init__(self, x, y, srid=None, **kwargs):
        # Call the base Point constructor
        super(self.__class__, self).__init__(x, y)

        # Store the SRID if provided
        if srid is not None:
            if srid not in srid_map:
                raise ValueError(f"Unknown SRID {srid}")
            self.srid = srid
        else:
            self.srid = None

        # Validate and set any additional fields
        for key, value in kwargs.items():
            if key not in fields:
                raise ValueError(f"Unexpected field '{key}' for {name}")
            setattr(self, key, value)

    # Optional: provide a readable representation
    def __repr__(self):
        field_str = ", ".join(f"{k}={getattr(self, k, None)!r}" for k in fields)
        return f"<{name} ({self.x}, {self.y}) srid={self.srid} {field_str}>"

    # Assemble the class dictionary
    attrs = {
        "__init__": __init__,
        "__repr__": __repr__,
        "fields": fields,
        "srid_map": srid_map,
    }

    # Dynamically create and return the new subclass of Point
    return type(name, (Point,), attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import warnings
    import functools
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    nums = []
    for p in parts:
        try:
            nums.append(int(p))
        except ValueError:
            # strip any non-digit suffix
            num = ''
            for ch in p:
                if ch.isdigit():
                    num += ch
                else:
                    break
            if num:
                nums.append(int(num))
            else:
                nums.append(0)
    return tuple(nums)

