def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    interface = {}
    if all:
        # Walk the method resolution order to collect all interface definitions
        for cls in reversed(self.__class__.__mro__):
            if hasattr(cls, "__interface__"):
                interface.update(cls.__interface__)
    else:
        interface = getattr(self.__class__, "__interface__", {})
    return interface

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # If the class explicitly lists its interface attributes, use that
    if hasattr(self, "ATTRIBS"):
        return list(self.ATTRIBS)

    # Otherwise, introspect the class dictionary for non-callable, non-private members
    if all:
        attrs = set()
        for cls in self.__class__.__mro__:
            for name, value in cls.__dict__.items():
                if not name.startswith("_") and not callable(value):
                    attrs.add(name)
        return sorted(attrs)
    else:
        return sorted(
            [
                name
                for name, value in self.__class__.__dict__.items()
                if not name.startswith("_") and not callable(value)
            ]
        )

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for arg in sequence:
        if arg is None:
            continue
        # Expand tuples or lists into individual elements
        if isinstance(arg, (tuple, list)):
            output.extend(arg)
        # Expand Declaration objects that expose a collection of interfaces
        elif hasattr(arg, 'specs'):
            output.extend(arg.specs)
        elif hasattr(arg, 'interfaces'):
            output.extend(arg.interfaces)
        else:
            # Assume arg is an individual interface or implements spec
            output.append(arg)
    return output

