def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is a single FillRequest instance, it's valid
    if isinstance(seq, FillRequest):
        return True
    # If seq is a Source instance, it's not valid
    if isinstance(seq, Source):
        return False
    # Avoid treating strings or bytes as iterables
    if isinstance(seq, (str, bytes)):
        return False
    # Try to iterate over seq
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    # Check if any element in the sequence is a FillRequest
    for item in seq:
        if isinstance(item, FillRequest):
            return True
    return False

