def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    errors = []

    # Regular expressions for keys and values (example patterns)
    key_regex = re.compile(r'^[A-Za-z0-9_\-\.]+$')
    value_regex = re.compile(r'^[A-Za-z0-9_\-\.]+$')

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_regex.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [{key_regex.pattern}]"})

        # Validate value(s)
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): 'expected string or bytes-like object'})
                else:
                    if not value_regex.match(v):
                        errors.append({v: f"Label value '{v}' does not match the regex [{value_regex.pattern}]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not value_regex.match(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [{value_regex.pattern}]"})

    if errors:
        raise ValidationError(messages=errors)

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Helper to handle nested dicts
    def _update_dict(target, schema, resp):
        for field in schema:
            if isinstance(field, dict):
                name = field.get("name")
                children = field.get("children")
            else:
                name = field
                children = None
            if not name:
                continue
            if name not in target:
                if name in resp:
                    target[name] = resp[name]
            else:
                # If the field is a nested structure, recurse
                if children:
                    child_resp = resp.get(name, {})
                    child_target = target.get(name, {})
                    if isinstance(child_resp, dict) and isinstance(child_target, dict):
                        _update_dict(child_target, children, child_resp)
                    elif isinstance(child_resp, list) and isinstance(child_target, list):
                        # Ensure the target list has enough items
                        for i, item_resp in enumerate(child_resp):
                            if i < len(child_target):
                                item_target = child_target[i]
                            else:
                                item_target = {}
                                child_target.append(item_target)
                            _update_dict(item_target, children, item_resp)

    # Main loop over the observer schema
    for field in observer_schema:
        if isinstance(field, dict):
            name = field.get("name")
            children = field.get("children")
        else:
            name = field
            children = None
        if not name:
            continue
        if name not in last_applied_manifest:
            if name in response:
                last_applied_manifest[name] = response[name]
        else:
            # If the field is a nested structure, recurse
            if children:
                child_resp = response.get(name, {})
                child_target = last_applied_manifest.get(name, {})
                if isinstance(child_resp, dict) and isinstance(child_target, dict):
                    _update_dict(child_target, children, child_resp)
                elif isinstance(child_resp, list) and isinstance(child_target, list):
                    # Ensure the target list has enough items
                    for i, item_resp in enumerate(child_resp):
                        if i < len(child_target):
                            item_target = child_target[i]
                        else:
                            item_target = {}
                            child_target.append(item_target)
                        _update_dict(item_target, children, item_resp)

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in response")
        if isinstance(sub_schema, dict):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, response[key]
            )
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a container for observer schemas
    if not hasattr(app, "observer_schema") or app.observer_schema is None:
        app.observer_schema = {}

    # Iterate over all resources defined in the application's manifest
    for resource in getattr(app.spec, "manifest", []):
        # Skip resources that already have a custom observer schema
        if hasattr(resource, "observer_schema") and resource.observer_schema is not None:
            continue

        # Determine a unique identifier for the resource (use metadata.name if available)
        name = getattr(getattr(resource, "metadata", None), "name", None)
        if not name:
            # If no name is available, fall back to the resource's kind and a generated id
            name = f"{resource.kind}-{id(resource)}"

        # Build a minimal default observer schema
        default_schema = {
            "kind": resource.kind,
            "metadata": {"name": name},
        }

        # Attach the schema to the resource itself (if the attribute exists)
        if hasattr(resource, "observer_schema"):
            resource.observer_schema = default_schema

        # Also store the schema in the application's central registry
        app.observer_schema[name] = default_schema

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    log = getattr(self, 'validation_log', None)
    if not log:
        return ''
    lines = []
    if isinstance(log, dict):
        for level, msgs in log.items():
            for msg in msgs:
                lines.append(f"{prefix}{level}: {msg}")
    else:
        for entry in log:
            if isinstance(entry, tuple) and len(entry) == 2:
                level, msg = entry
                lines.append(f"{prefix}{level}: {msg}")
            elif hasattr(entry, 'level') and hasattr(entry, 'message'):
                lines.append(f"{prefix}{entry.level}: {entry.message}")
            else:
                lines.append(f"{prefix}{entry}")
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Determine spec version
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get('type')
        if isinstance(type_val, str):
            # Expect format like 'FoLiA 1.0' or 'FoLiA 2.0'
            parts = type_val.split()
            if parts and parts[-1].replace('.', '').isdigit():
                try:
                    spec_version = float(parts[-1])
                except ValueError:
                    pass
    # Basic validation: inventory must be a dict
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")
    # Check required keys
    required_keys = ['id', 'type', 'content']
    missing = [k for k in required_keys if k not in inventory]
    if missing:
        raise ValueError(f"Inventory missing required keys: {missing}")
    # Validate id format
    if not isinstance(inventory['id'], str) or not inventory['id']:
        raise ValueError("Inventory 'id' must be a non-empty string")
    # Validate type matches spec_version
    if inventory.get('type') and spec_version:
        if f"{spec_version:.1f}" not in inventory['type']:
            raise ValueError(f"Inventory type '{inventory['type']}' does not match spec version {spec_version}")
    # Additional checks could be added here based on spec_version
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # manifest_files: mapping of file names to digest strings
    # digests_used: set of digest strings that should be present in the manifest
    missing = set()
    unused = set()

    # Ensure every needed digest is present in the manifest
    for digest in digests_used:
        if digest not in manifest_files.values():
            missing.add(digest)

    # Ensure every digest in the manifest is actually used
    for digest in manifest_files.values():
        if digest not in digests_used:
            unused.add(digest)

    if missing:
        raise ValueError(f"Missing digests in manifest: {', '.join(sorted(missing))}")
    if unused:
        raise ValueError(f"Unused digests in manifest: {', '.join(sorted(unused))}")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Ensure both inventories have a version attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("Both inventories must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(
            f"Prior inventory version ({prior.version}) must be older than current inventory version ({self.version})"
        )

    # Ensure both inventories have an inventory mapping
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both inventories must have an 'inventory' attribute")
    if not isinstance(self.inventory, dict) or not isinstance(prior.inventory, dict):
        raise TypeError("Inventory attributes must be dictionaries")

    # Check that all items in the prior inventory exist in the current inventory
    missing = [key for key in prior.inventory if key not in self.inventory]
    if missing:
        raise ValueError(
            f"Prior inventory contains items not present in current inventory: {missing}"
        )

    # Optionally, ensure that the items themselves are unchanged
    for key, prior_item in prior.inventory.items():
        current_item = self.inventory[key]
        if prior_item != current_item:
            raise ValueError(f"Item '{key}' differs between prior and current inventory")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Initialise the mapping
    path_map = {}

    # Helper to add entries from a given version
    def _add_entries(ver):
        entries = inventory.get(ver, [])
        for entry in entries:
            # Support both dict and tuple/list representations
            if isinstance(entry, dict):
                logical_path = entry.get("logical_path")
                content_file = entry.get("content_file")
            else:
                # Assume (logical_path, content_file) tuple
                logical_path, content_file = entry[0], entry[1]
            if logical_path is None or content_file is None:
                continue
            path_map.setdefault(logical_path, set()).add(content_file)

    # Add entries for the requested version
    _add_entries(version)

    # Include duplicates from later versions
    for later_version in sorted(inventory.keys()):
        if later_version <= version:
            continue
        _add_entries(later_version)

    return path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Basic type checks
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary.")
        if 'files' not in fixity:
            raise ValueError("Fixity block missing 'files' key.")
        files = fixity['files']
        if not isinstance(files, list):
            raise ValueError("'files' must be a list.")
        # Ensure manifest_files is iterable of strings
        if not hasattr(manifest_files, '__contains__'):
            raise ValueError("manifest_files must support membership tests.")
        seen = set()
        for idx, entry in enumerate(files):
            if not isinstance(entry, dict):
                raise ValueError(f"File entry at index {idx} must be a dictionary.")
            if 'path' not in entry or 'hash' not in entry:
                raise ValueError(f"File entry at index {idx} missing required 'path' or 'hash' keys.")
            path = entry['path']
            if path not in manifest_files:
                raise ValueError(f"File '{path}' referenced in fixity block is not present in the manifest.")
            if path in seen:
                raise ValueError(f"Duplicate file reference '{path}' in fixity block.")
            seen.add(path)
        return True

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    xml_basenames = set()
    for root, dirs, files in os.walk(folder):
        for f in files:
            if f.lower().endswith('.xml'):
                base = os.path.splitext(f)[0]
                xml_basenames.add(base)
    data = {}
    for root, dirs, files in os.walk(folder):
        for f in files:
            base, ext = os.path.splitext(f)
            if base in xml_basenames:
                data.setdefault(base, []).append(os.path.join(root, f))
    return data

def add_asset(self, basename, file_path):
    """Add an asset to the element.

    Parameters:
        basename (str): The base name of the asset file.
        file_path (str): The full path to the asset file.

    Raises:
        ValueError: If the basename already exists.
    """
    if not hasattr(self, 'assets'):
        self.assets = {}
    if basename in self.assets:
        raise ValueError(f"Asset with basename '{basename}' already exists.")
    self.assets[basename] = file_path

