def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _traverse(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                obj.validate()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Validation warning for {obj}: {e}")

        if check_digests:
            try:
                obj.check_digest()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Digest warning for {obj}: {e}")

        if valid:
            good_objects += 1

        # Recurse into children if the object exposes a 'children' attribute
        children = getattr(obj, 'children', None)
        if children is not None:
            for child in children:
                _traverse(child)
        else:
            # Fallback: try to iterate over the object itself
            try:
                for child in obj:
                    _traverse(child)
            except TypeError:
                pass

    _traverse(self)
    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    # Ensure we have a place to store differences
    self.different_digests = {}

    # Helper to parse an inventory file into a dict of {path: digest}
    def _parse_inventory(inv_path):
        tree = ET.parse(inv_path)
        root = tree.getroot()
        inv = {}
        for file_elem in root.findall('.//file'):
            path = file_elem.get('path')
            digest = file_elem.get('digest')
            if path and digest:
                inv[path] = digest
        return inv

    # The root inventory is assumed to be available on the instance; fall back to empty dict
    root_inventory = getattr(self, 'root_inventory', {})

    for vdir in version_dirs:
        inv_path = os.path.join(vdir, 'inventory.xml')
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Inventory file missing in version directory '{vdir}'")
        inv = _parse_inventory(inv_path)

        # Check that the inventory contains all files up to this point
        for path, digest in inv.items():
            root_digest = root_inventory.get(path)
            if root_digest is None:
                # File not present in the root inventory; ignore or log
                continue
            if digest != root_digest:
                self.different_digests.setdefault(path, []).append((vdir, digest))

    return self.different_digests

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.exists(path):
        return f"Path does not exist: {path}"
    if os.path.isfile(path):
        return 'file'
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except OSError as e:
            return f"Cannot list directory {path}: {e}"
        namaste_files = [f for f in entries if f.startswith('0=')]
        if not namaste_files:
            return f"No Namaste file found in directory: {path}"
        if 'objects' in entries:
            return 'root'
        if 'versions' in entries:
            return 'object'
        return f"Directory {path} contains Namaste file but no 'objects' or 'versions' subdirectory"
    return f"Unknown path type: {path}"

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Empty size string")
    unit = size[-1]
    if unit.isalpha():
        num_part = size[:-1]
        unit = unit.upper()
    else:
        num_part = size
        unit = ''
    try:
        num = float(num_part)
    except ValueError:
        raise ValueError(f"Invalid size value: {size}")
    factor = 1
    if unit == 'K':
        factor = 1000
    elif unit == 'M':
        factor = 1000**2
    elif unit == 'G':
        factor = 1000**3
    elif unit == 'T':
        factor = 1000**4
    elif unit == 'P':
        factor = 1000**5
    elif unit == 'E':
        factor = 1000**6
    elif unit != '':
        raise ValueError(f"Unknown unit: {unit}")
    return int(round(num * factor))

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

