def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    import sys

    # Normalise inputs
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        args = [args]

    results = []

    for cmd in commands:
        # Convert command to a list of arguments
        if isinstance(cmd, str):
            cmd_list = shlex.split(cmd)
        else:
            cmd_list = list(cmd)

        full_cmd = cmd_list + list(args)

        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
                text=True,
                check=True
            )
            if not hide_stderr and result.stderr:
                print(result.stderr, file=sys.stderr)
            results.append(result)
        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command '{' '.join(full_cmd)}' failed with return code {e.returncode}")
            raise

    return results

