    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        handler = cls._protocol_handlers.get(protocol_version)
        return {protocol_version: handler} if handler else {}
    return dict(cls._protocol_handlers)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it unchanged
    if isinstance(seq, (list, tuple, set, str, bytes, bytearray, memoryview)):
        return seq, type(seq)

    # If seq is a file-like object, read its content
    if hasattr(seq, 'read'):
        data = seq.read() if bufsize is None else seq.read(bufsize)
        if isinstance(data, (list, tuple, set, str, bytes, bytearray, memoryview)):
            return data, type(data)
        try:
            data = list(data)
        except TypeError:
            pass
        return data, type(data)

    # If seq is an iterator or generator, materialize it
    try:
        seq = list(seq)
    except TypeError:
        # seq is not iterable, return as is
        return seq, type(seq)
    return seq, type(seq)

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # If iface is a tuple of classes, any match is sufficient
    if isinstance(iface, tuple):
        for cls in iface:
            if verifyClass(cls, candidate, tentative):
                return True
        return False

    # If candidate is a class
    if isinstance(candidate, type):
        # Direct subclass check
        try:
            if issubclass(candidate, iface):
                return True
        except TypeError:
            pass  # candidate or iface not a class

        # Check that candidate implements all callable attributes of iface
        for name in dir(iface):
            attr = getattr(iface, name, None)
            if callable(attr):
                if not hasattr(candidate, name):
                    if tentative:
                        return True
                    return False
        return True

    # If candidate is an instance
    if isinstance(candidate, iface):
        return True

    # For arbitrary objects, check that they provide all callable attributes of iface
    for name in dir(iface):
        attr = getattr(iface, name, None)
        if callable(attr):
            if not hasattr(candidate, name):
                if tentative:
                    return True
                return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        # In Python 2, __metaclass__ could be a string; we ignore that case
        if isinstance(explicit_mc, str):
            raise TypeError("Explicit metaclass must be a type, not a string")
        return explicit_mc

    if not bases:
        return type

    # Find the most derived metaclass among the bases
    metaclass = type(bases[0])
    for base in bases[1:]:
        base_meta = type(base)
        if issubclass(base_meta, metaclass):
            metaclass = base_meta
        elif not issubclass(metaclass, base_meta):
            raise TypeError("metaclass conflict: %s and %s" % (metaclass, base_meta))
    return metaclass

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('popitem from an empty cache')
    # Find the key with the lowest frequency
    min_freq = min(self._freq.values())
    for key, freq in self._freq.items():
        if freq == min_freq:
            break
    value = self._cache.pop(key)
    self._freq.pop(key)
    return key, value

