def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url.startswith(('http://', 'https://')):
        raise ValueError("url must be a string starting with http:// or https://")

    # Default document path if none provided
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    else:
        # Ensure the path starts with a slash
        if not document_path.startswith('/'):
            document_path = '/' + document_path

    # Build the full href for the NodeInfo document
    base = url.rstrip('/')
    href = base + document_path

    # Construct the .well-known NodeInfo document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        data = json.loads(document)
        # Expect keys: subject, links
        subject = data.get("subject") or data.get("Subject")
        links = []
        for link in data.get("links", []):
            # Each link may be a dict with rel, href, type, etc.
            links.append({
                "rel": link.get("rel"),
                "href": link.get("href"),
                "type": link.get("type"),
                "title": link.get("title"),
            })
        return {"subject": subject, "links": links}
    except (json.JSONDecodeError, TypeError):
        pass  # Not JSON, try XRD

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Document is neither valid JSON nor XRD XML") from e

    # Helper to strip namespace
    def _strip_ns(tag):
        return tag.split("}")[-1] if "}" in tag else tag

    subject = None
    links = []

    for elem in root.iter():
        tag = _strip_ns(elem.tag)
        if tag == "Subject" and subject is None:
            subject = elem.text
        elif tag == "Link":
            rel = elem.attrib.get("rel")
            href = elem.attrib.get("href")
            type_ = elem.attrib.get("type")
            title = elem.attrib.get("title")
            links.append({
                "rel": rel,
                "href": href,
                "type": type_,
                "title": title,
            })

    if subject is None:
        raise ValueError("XRD document missing <Subject> element")

    return {"subject": subject, "links": links}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        resp = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (resp.status_code, None)
    except Exception as e:
        return (None, e)

@classmethod
