@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("No spec content provided")
    if isinstance(spec_content, str):
        try:
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Failed to parse YAML: {e}")
    elif isinstance(spec_content, dict):
        data = spec_content
    else:
        raise IRValidatorException("Spec content must be a YAML string or dict")
    required_fields = ['name', 'version', 'description']
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")
    return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("No YAML file provided")
    try:
        with open(yaml_file, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary at the top level")
    # Validate required fields if defined on the class
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")
    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Pull defaults from the element's spec dictionary if present
    spec = getattr(self, 'spec', None)
    if isinstance(spec, dict):
        for key, value in spec.items():
            # Only add if the attribute is not already set
            if not hasattr(self, key) or getattr(self, key) is None:
                defaults[key] = value
    # Merge with any global defaults defined on the class
    class_defaults = getattr(self.__class__, 'DEFAULTS', {})
    for key, value in class_defaults.items():
        defaults.setdefault(key, value)
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # If the parser exposes a dedicated method, use it
    if hasattr(self, 'parser') and hasattr(self.parser, 'get_option_specs'):
        return self.parser.get_option_specs(command_name)

    # Fallback: iterate over the parser's options collection
    options = []
    for opt in getattr(self.parser, 'options', []):
        if getattr(opt, 'command', None) == command_name:
            options.append(opt)
    return options

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Retrieve the command object from the registry
    commands = getattr(self, "commands", None)
    if commands is None:
        raise AttributeError("The object has no 'commands' attribute")

    command = commands.get(command_name)
    if command is None:
        raise KeyError(f"Command '{command_name}' not found")

    # Retrieve the option specification from the command
    options = getattr(command, "options", {})
    spec = options.get(argument_name)
    if spec is None:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    # If args is a mapping, assume keys are argument names and values are the argument objects
    if isinstance(args, dict):
        for name, value in args.items():
            if isinstance(value, dict):
                if value.get('silent'):
                    silent.append(name)
            else:
                if getattr(value, 'silent', False):
                    silent.append(name)
    # If args is an iterable of tuples/lists (name, value)
    elif hasattr(args, '__iter__'):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                name, value = item
                if isinstance(value, dict):
                    if value.get('silent'):
                        silent.append(name)
                else:
                    if getattr(value, 'silent', False):
                        silent.append(name)
            else:
                # Fallback: try to get name and silent flag from object attributes
                name = getattr(item, 'name', None)
                value = getattr(item, 'value', None)
                if value is None:
                    value = item
                if isinstance(value, dict):
                    if value.get('silent'):
                        if name:
                            silent.append(name)
                else:
                    if getattr(value, 'silent', False):
                        if name:
                            silent.append(name)
    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            # Skip options that do not have a required_when clause
            if 'required_when' not in opt:
                continue

            cond = opt['required_when']
            # If the condition is a callable, call it with the args dict
            if callable(cond):
                try:
                    if cond(args):
                        required.append(opt['name'])
                except Exception:
                    # If the callable raises, ignore this option
                    continue
            else:
                # Assume the condition is a string expression that can be evaluated
                # against the args dictionary.  Use a restricted eval context.
                try:
                    if eval(cond, {}, args):
                        required.append(opt['name'])
                except Exception:
                    # If eval fails, ignore this option
                    continue

        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
    # Determine max lengths mapping
    max_lengths = getattr(self, 'max_lengths', None)
    if max_lengths is None:
        max_lengths = getattr(self, 'MAX_LENGTHS', {})
    for name, value in args.items():
        if name in max_lengths:
            max_len = max_lengths[name]
            if hasattr(value, '__len__') and len(value) > max_len:
                raise ValueError(f"Argument '{name}' length {len(value)} exceeds maximum allowed {max_len}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine global bounds if defined
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)
    if min_val is None or max_val is None:
        # No bounds to enforce
        return True

    # Support both dict and iterable of values
    if isinstance(args, dict):
        iterable = args.items()
    else:
        iterable = [(None, v) for v in args]

    for name, value in iterable:
        if value is None:
            continue
        try:
            if value < min_val or value > max_val:
                raise ValueError(f"Argument '{name}' with value {value} is out of bounds [{min_val}, {max_val}].")
        except TypeError:
            raise TypeError(f"Argument '{name}' with value {value} is not comparable to bounds.")
    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Dynamically create a type class for the complex argument
    def _init(self, spec):
        self.spec = spec
        self.subcommand = subcommand
        self.option_name = option_name

    def _call(self, value):
        # If the spec defines a custom parse function, use it
        parse_func = getattr(self.spec, 'parse', None)
        if callable(parse_func):
            return parse_func(value)
        # Default behaviour: return the raw value
        return value

    ComplexType = type(
        type_name,
        (object,),
        {
            '__init__': _init,
            '__call__': _call,
        }
    )

    return ComplexType(spec_option)

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, tuple) and len(item) == 2:
                vars_dict[item[0]] = item[1]
            elif isinstance(item, str) and "=" in item:
                key, val = item.split("=", 1)
                vars_dict[key] = val
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the base command
    cmd = ['ansible-playbook', playbook_path]

    # Add verbosity flags if requested
    if verbose:
        try:
            level = int(verbose)
        except Exception:
            level = 0
        for _ in range(level):
            cmd.append('-v')

    # Add extra variables if provided
    if extra_vars:
        # Assume json is available in the environment
        cmd.extend(['--extra-vars', json.dumps(extra_vars)])

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            flag = '--' + key
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif value is not None:
                cmd.extend([flag, str(value)])

    # Log the command for debugging purposes
    if hasattr(ir_plugin, 'log'):
        ir_plugin.log('Running ansible-playbook: ' + ' '.join(cmd))
    else:
        print('Running ansible-playbook:', ' '.join(cmd))

    # Execute the command and capture output
    result = subprocess.run(cmd, capture_output=True, text=True)

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # A mapping of parser names to expected argument types.
    # Example: {'main': {'count': int, 'verbose': bool, 'tags': list}}
    type_map = getattr(self, "_arg_type_map", {})

    # If we don't have a mapping for this parser, nothing to do.
    if parser_name not in type_map:
        return

    for key, expected_type in type_map[parser_name].items():
        if key not in values_dict:
            continue

        raw_value = values_dict[key]
        try:
            # Handle boolean specially because str(bool) is not what we want.
            if expected_type is bool:
                if isinstance(raw_value, str):
                    lowered = raw_value.lower()
                    if lowered in ("true", "1", "yes", "on"):
                        casted = True
                    elif lowered in ("false", "0", "no", "off"):
                        casted = False
                    else:
                        raise ValueError
                else:
                    casted = bool(raw_value)
            # Handle list/tuple types by casting each element.
            elif expected_type in (list, tuple):
                if isinstance(raw_value, str):
                    # Assume comma separated values for strings.
                    items = [item.strip() for item in raw_value.split(",")]
                else:
                    items = list(raw_value)
                casted = expected_type(items)
            else:
                casted = expected_type(raw_value)
        except Exception:
            # If conversion fails, keep the original value.
            casted = raw_value

        values_dict[key] = casted

    # The values_dict is modified in place; no return value is needed.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_path):
        raise FileNotFoundError(f"plugin.json not found in {plugin_dir}")

    with open(spec_path, "r", encoding="utf-8") as f:
        spec = json.load(f)

    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if not os.getenv('CONFIG_PATH'):
        path = getattr(self, 'config_path', None)
        if path:
            os.environ['CONFIG_PATH'] = path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("Root cannot be empty.")
    # Normalize root: remove trailing slash or backslash
    if root.endswith('/') or root.endswith('\\'):
        root = root.rstrip('/\\')
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    stripped = path[len(root):]
    # Remove leading slash or backslash if present
    if stripped.startswith('/') or stripped.startswith('\\'):
        stripped = stripped[1:]
    return stripped
